create table if not exists public.overlay_artwork_members (
reference_id text primary key references public.overlay_art_references(id),
artwork_key text not null,
language text not null check(language in ('ko','ja','en')),
mapping_basis text not null default 'reference'
);
create index if not exists overlay_artwork_members_key_idx on public.overlay_artwork_members(artwork_key);
create table if not exists public.overlay_layer_assets (
cache_key text primary key,
layer_kind text not null check(layer_kind in ('text','illustration')),
generation_id uuid not null references public.overlay_generations(id),
source_reference_id text not null references public.overlay_art_references(id),
prompt_version text not null,
created_at timestamptz not null default now()
);
alter table public.overlay_artwork_members enable row level security;
alter table public.overlay_layer_assets enable row level security;
revoke all on public.overlay_artwork_members,public.overlay_layer_assets from anon,authenticated;
grant all on public.overlay_artwork_members,public.overlay_layer_assets to service_role;
insert into public.overlay_artwork_members(reference_id,artwork_key,language)
select id,id,source_language from public.overlay_art_references
where (id like '30th-en-%' or id like 'm6a-%') and source_language in ('ko','ja','en')
on conflict(reference_id) do nothing;

